const message = $input.item.json.message;
if (!message) return [];
const text = message.text || '';
const chatId = String(message.chat?.id || '');

// Solo mensajes con emojis de reaccion Intel
const intelEmojis = ['👍','👎','💬','⚡','❓'];
if (!intelEmojis.some(e => text.includes(e))) return [];

const dateStr = new Date().toLocaleDateString('es-ES', {day:'2-digit',month:'2-digit',year:'numeric'});
const todayKey = new Date().toISOString().slice(0,10).replace(/-/g,'');

// Parsear pares emoji+numero: 👍1 👎2 ⚡3
const results = [];
const matches = [...text.matchAll(/([👍👎💬⚡❓])(\d+)/gu)];

if (matches.length === 0) return [];

const comment = text.replace(/[👍👎💬⚡❓]\d+/gu,'').trim();

for (const m of matches) {
  const reaction = m[1];
  const sigNum = parseInt(m[2]);
  // forge: señales 1-5, horizon: señales 6-9
  const agent = sigNum <= 5 ? 'forge' : 'horizon';
  results.push({
    json: {
      date: dateStr,
      signal_id: `${todayKey}-${agent}-${sigNum}`,
      agent,
      signal_num: String(sigNum),
      reaction,
      comment: comment || '',
      chat_id: chatId
    }
  });
}
return results;
